function rewriteSequence(scale=1,grid=0,shift=0){if(playing){status('Arrêtez la lecture pour modifier le placement des notes.');return}remember();const pattern=currentPattern,length=sequenceLength(),indices=$('#correctScope').value==='all'?pads.map((_,i)=>i):[selected];for(const i of indices){const p=pads[i],old=p.patterns[pattern];if(!old)continue;const events=[];for(let s=0;s<length;s++)if(old[s])for(const e of notesAt(p,pattern,s)){let position=(s+e.offset)*scale;if(grid)position=Math.round(position/grid)*grid;position+=shift;position=((position%length)+length)%length;const target=Math.round(position)%length;events.push({target,event:{...e,offset:Math.max(-.49,Math.min(.49,position-Math.round(position))),duration:Math.min(128,e.duration*scale)}})}p.patterns[pattern]=Array(length).fill(false);for(const key of Object.keys(p.events))if(+key.split(':')[0]===pattern)delete p.events[key];for(const e of events){putNote(p,pattern,e.target+e.event.offset,e.event)}}renderSteps();changed();status('Placement des notes modifié. Annuler restaure la séquence précédente. Les collisions sur un même pas gardent la dernière note.')}
$('#timeCorrect').onclick=()=>rewriteSequence(1,16/(+$('#correctGrid').value||16),(+$('#correctShift').value||0)/1000/(60/tempo()/4));$('#sequenceHalfSpeed').onclick=()=>rewriteSequence(2);$('#sequenceDoubleSpeed').onclick=()=>rewriteSequence(.5);
$('#renderPad').onclick=async()=>{try{const target=typeof chosenResamplePad==='function'?chosenResamplePad():pads.findIndex(p=>p.data.length===1);if(target<0)throw Error('Aucun pad vide.');const previous=$('#exportSource').value,repeats=$('#exportBars').value;$('#exportSource').value='pattern';$('#exportBars').value=1;let buffer;try{buffer=(await renderMix()).buffer}finally{$('#exportSource').value=previous;$('#exportBars').value=repeats}if(pads[target].data.length!==1)throw Error('Le pad cible a changé pendant le rendu.');if(pads.reduce((n,p)=>n+p.data.length*(p.right?2:1),0)+buffer.length*2>sr*240)throw Error('Mémoire audio pleine.');remember();Object.assign(pads[target],{data:buffer.getChannelData(0).slice(),right:buffer.getChannelData(1).slice(),start:0,end:1,name:'SEQ '+sequenceName(currentPattern),volume:1});updateSelected(target);changed();status('Séquence rendue, effets inclus, sur '+padName(target)+'.')}catch(e){status(e.message)}};
$('#songSequence').onclick=()=>{try{if(playing)throw Error('Arrêtez la lecture avant de fusionner le morceau.');const order=songOrder(),plan=sequencePlan(order),bars=plan.reduce((n,e)=>n+e.bars,0);if(bars>128)throw Error('Fusion limitée à 128 mesures.');const target=Array.from({length:128},(_,i)=>i).find(i=>!pads.some(p=>p.patterns[i]?.some(Boolean)));if(target===undefined)throw Error('Aucune séquence vide.');if(tempoMode==='sequence'&&new Set(order.map(i=>sequenceTempos[i])).size>1)throw Error('Les séquences ont des tempos différents. Utilisez le rendu WAV pour conserver ces changements.');remember();const snapshots=pads.map(p=>({patterns:p.patterns.map(a=>a?.slice()||null),events:{...p.events},automation:{...p.automation}}));sequenceBars[target]=bars;sequenceTempos[target]=sequenceTempos[order[0]];for(let i=0;i<pads.length;i++){const p=pads[i],source=snapshots[i];p.patterns[target]=null;for(const k of Object.keys(p.events))if(+k.split(':')[0]===target)delete p.events[k];for(const k of Object.keys(p.automation||{}))if(+k.split(':')[0]===target)delete p.automation[k];for(const e of plan)for(let s=0;s<sequenceLength(e.pattern);s++){const dest=e.offset*barSteps()+s;if(source.patterns[e.pattern]?.[s]){stepsFor(p,target)[dest]=true;const note=source.events[e.pattern+':'+s];if(note)p.events[target+':'+dest]=cloneEvent(note)}const point=source.automation[e.pattern+':'+s];if(point){p.automation??={};p.automation[target+':'+dest]={...point}}}}currentPattern=target;sequencePage=0;renderPatterns();renderSteps();changed();status('Morceau fusionné dans la séquence '+sequenceName(target)+'.')}catch(e){status(e.message)}};
$('#continuePlay').onclick=()=>{if(playing)return;resumeStep=step;$('#play').onclick()};
for(const p of pads)Object.assign(p,cleanExtraPad(p));if(restoredExtra)restorePerformance(restoredExtra);else renderExtra();

function normalizeMasterComp(p={}){p=p&&typeof p==='object'?p:{};const bound=(k,a,b,d)=>Number.isFinite(p[k])?Math.max(a,Math.min(b,p[k])):d;return {enabled:!!p.enabled,color:!!p.color,attack:bound('attack',.1,150,10),release:bound('release',3,300,120),amount:bound('amount',0,100,40),boost:bound('boost',0,24,0)}}
function createMasterDynamics(c,input,destination,settings){const p=normalizeMasterComp(settings);if(!p.enabled){input.connect(destination);return {dispose(){try{input.disconnect(destination)}catch{}}}}const boost=c.createGain(),comp=c.createDynamicsCompressor(),makeup=c.createGain(),color=c.createBiquadFilter(),shape=c.createWaveShaper(),nodes=[boost,comp,makeup,color,shape];boost.gain.value=10**(p.boost/20);const a=p.amount/100;comp.threshold.value=-6-36*a;comp.ratio.value=1+11*a;comp.attack.value=p.attack/1000;comp.release.value=p.release/1000;comp.knee.value=12;makeup.gain.value=10**(a*3/20);color.type='lowshelf';color.frequency.value=180;color.gain.value=p.color?3:0;const curve=new Float32Array(2048);for(let i=0;i<curve.length;i++){const x=i/(curve.length-1)*2-1;curve[i]=Math.tanh(x*1.5)/Math.tanh(1.5)}shape.curve=curve;input.connect(boost).connect(comp).connect(makeup).connect(color);if(p.color)color.connect(shape).connect(destination);else color.connect(destination);return {dispose(){try{input.disconnect(boost)}catch{}for(const node of nodes)node.disconnect()}}}
function syncMasterCompUI(){$('#masterCompEnabled').checked=masterCompSettings.enabled;$('#masterCompColor').checked=masterCompSettings.color;for(const [id,key]of [['masterCompAttack','attack'],['masterCompRelease','release'],['masterCompAmount','amount'],['masterCompBoost','boost']])$('#'+id).value=masterCompSettings[key]}
function rebuildMasterComp(){if(!ctx)return;masterDynamics?.dispose();masterDynamics=createMasterDynamics(ctx,masterBus,outputBus,masterCompSettings)}
for(const id of ['masterCompEnabled','masterCompColor','masterCompAttack','masterCompRelease','masterCompAmount','masterCompBoost']){$('#'+id).addEventListener('pointerdown',remember);$('#'+id).onchange=()=>{remember();masterCompSettings=normalizeMasterComp({enabled:$('#masterCompEnabled').checked,color:$('#masterCompColor').checked,attack:+$('#masterCompAttack').value,release:+$('#masterCompRelease').value,amount:+$('#masterCompAmount').value,boost:+$('#masterCompBoost').value});rebuildMasterComp();changed()}}
syncMasterCompUI();

$('#audioDiagnostic').onclick=async()=>{try{await ensureFlex();$('#diagnosticState').textContent='Moteur temporel et mémoire audio : initialisation réussie. Vos sons restent inchangés.'}catch(e){$('#diagnosticState').textContent='Moteur indisponible : '+e.message}};

function warmPerformance(){if(ctx?.audioWorklet&&!flexPromise)ensureFlex(true).catch(()=>{})}
function startFlexTransport(time){if(!flexNode||!flexSettings.type)return;const type=flexSettings.type,needsHistory=!(type>=9&&type<=11),delay=Math.max(0,time-ctx.currentTime)+(needsHistory?60/tempo()*barSteps()/4:0);flexNode.port.postMessage({...flexSettings,bpm:tempo(),beats:barSteps()/4,delay:delay*ctx.sampleRate})}

function applyLivePadParameter(i,key,value){if(!ctx)return;const p=pads[i],time=ctx.currentTime;for(const v of voices)if(v.index===i&&v.stopTime===undefined){if(key==='volume')v.g.gain.setTargetAtTime(value*v.velocity,time,.005);if(key==='pan')v.pan.pan.setTargetAtTime(value,time,.005);if(key==='filter')for(const n of [v.f,...(v.filterNodes||[])])n.frequency?.setTargetAtTime(Math.min(value,ctx.sampleRate*.49),time,.005);if(key==='pitch'||key==='fine')v.source.playbackRate.setTargetAtTime(2**((p.pitch+(p.fine||0)/100+v.notePitch)/12)*(v.pad.warpRate||1),time,.005);if(key==='release')v.release=value;if(key==='filterRelease')v.filterRelease=value}}
